const grafanaHost = 'GRAFANA_HOST';

// Pairs each Prometheus answer with the check that asked it, by position.
const checks = $('Build checks').all().map((item) => item.json);
const answers = $input.all();

const lines = [];
const findings = [];

for (let index = 0; index < checks.length; index++) {
  const check = checks[index];
  const series = answers[index]?.json?.data?.result ?? [];

  if (series.length === 0) {
    findings.push(check.name);
    lines.push('\u26a0\ufe0f ' + check.name + ': no data');
    continue;
  }

  const value = Number(series[0].value[1]);
  const reading = value + (check.unit ?? '');
  const isFinding =
    (check.warnAbove !== undefined && value > check.warnAbove) ||
    (check.warnBelow !== undefined && value < check.warnBelow);

  if (isFinding) findings.push(check.name + ': ' + reading);
  lines.push((isFinding ? '\u26a0\ufe0f ' : '\u2022 ') + check.name + ': ' + reading);
}

const subject = findings.length
  ? 'Cluster digest \u2014 ' + findings.length + (findings.length === 1 ? ' finding' : ' findings')
  : 'Cluster digest \u2014 all clear';

const content = [
  findings.length ? 'Needs a look:' : 'Nothing needs a look.',
  findings.length ? findings.map((finding) => '  ' + finding).join('\n') : '',
  '',
  'Every check:',
  lines.join('\n'),
  '',
  'Dashboards and alert history: http://' + grafanaHost + '/',
].filter((part) => part !== '').join('\n');

return [{ json: { subject, content } }];
